function ActivityCrisisContractRankDialog:OnInitialize()
    xTry(function()
        local activityData = ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityData()
        self.activityData = activityData
        GameUtils.Request(Interfaces.ActivityStrangeTaleRank,{activityUuid = activityData.id },function(request,response)
            if checkInt(response.errCode) == 0 then
                self:RefreshUI(response.data)
            end
        end)
    end)
end

function ActivityCrisisContractRankDialog:RefreshUI(data)
    self.rankInfo = data
    self.rankData = data.rank
    self.myRankData = data.playerRank
    self.myRankData.percentageRank = checkNumber(data.percentageRank)
    GameUtils.HidePreviousDialogs(self.controller)
    if IsNull(self.rankData) or #self.rankData == 0 then
        self:ShowBlank(true)
    else
        self:RefreshMyselfNode()
        self:RefreshLoopViewList(#self.rankData)
        self:ShowBlank(false)
    end
end

