function ActivityCrisisContractRankDialog:ShowBlank(state)
    KTool.SetActive(self.RT_MyRankNode, not state)
    KTool.SetActive(self.RT_EmptyNode, state)
end

--- 更新显示我自己的排行信息
function ActivityCrisisContractRankDialog:RefreshMyselfNode()
    local LB_myCell = GetLuaBehaviour(self.RT_MyRankNode.gameObject, RankCellLuaPath)
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    self.myRankData.avatar = playerComponent.playerDojo.playerAvatar
    self.myRankData.avatarFrame = playerComponent.playerDojo.playerAvatarFrame
    self.myRankData.level = playerComponent.playerDojo.level
    self.myRankData.name = playerComponent.playerDojo.playerName
    self.myRankData.playerId = playerComponent.playerDojo.playerId
    LB_myCell.Env:Refresh(self.myRankData)
end

--- 排行榜列表
---@param maxNum any
function ActivityCrisisContractRankDialog:RefreshLoopViewList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
        self.LoopListView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function ActivityCrisisContractRankDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.gameObject, RankCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
        -- 第一页的节点播放延迟出现的动画
        if index + 1 <= loopListView.DisplayItemCount then
            CfUtils.PlayDelayShowAnimation(cell, index)
        end
    end
    local data = self.rankData[index + 1]
    local LT_cell = LB_cell.Env
    LT_cell:SetComponent(self.comp)
    LT_cell:Refresh(data)

    return cell
end

return ActivityCrisisContractRankDialog
